// Prompt source of truth: prompts/image-gen-draft.md — keep in sync.
const input = $input.first().json;
let body = (input && input.body !== undefined) ? input.body : input;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = {}; } }
body = body || {};
const ask = (body.ask || '').toString().trim();
if (!ask) throw new Error('ask is required');
const brand_name = (body.brand_name || 'Untitled brand').toString();
const brief = (body.brief || '').toString().trim();
const sizes = Array.isArray(body.sizes) ? body.sizes : [];
const references = (Array.isArray(body.references) ? body.references : [])
  .filter(r => r && r.b64)
  .slice(0, 6);
const previous_prompt = (body.previous_prompt || '').toString().trim();
const change_note = (body.change_note || '').toString().trim();

const system = "You are an art director writing prompts for an image-generation model
(Gemini 2.5 Flash Image). The model will receive your prompt **plus the
same reference images you are looking at**, so it can see the brand's
visual style directly.

Your job:
1. Study the reference images: palette, lighting, photographic vs.
   illustrated style, composition, typography treatment, mood.
2. Write ONE generation prompt that fulfils the ask in that brand style.
   Be concrete: subject, setting, composition, camera/angle, lighting,
   palette (name the actual colours), mood, and any on-image text in
   double quotes. 60–160 words. No aspect ratio or pixel sizes — those
   are added per size at render time.
3. Check the prompt against the brand brief. List every rule it breaks or
   risks breaking (wrong colours, forbidden imagery, tone, logo misuse,
   missing required elements). If the brief is empty, say so as an issue.

Return ONLY valid JSON, no markdown fences or commentary:

```json
{
  "prompt": "the generation prompt",
  "brief_check": {
    "passes": true,
    "issues": ["each rule broken or at risk, empty if none"],
    "notes": "one sentence on how the prompt follows the brief"
  }
}
```";

let text = 'Brand: ' + brand_name + '

Brand brief:
' + (brief || '(no brief written yet)') +
  '

Ask: ' + ask + '

Output sizes: ' + (sizes.join(', ') || 'post');
if (previous_prompt && change_note) {
  text += '

Previous prompt:
' + previous_prompt +
    '

Reviewer's requested changes:
' + change_note +
    '
Rewrite the previous prompt to apply these changes. Keep everything the reviewer did not ask to change.';
}
if (!references.length) text += '

(No reference images were selected — infer the style from the brief alone.)';

const content = references.map(r => ({
  type: 'image',
  source: { type: 'base64', media_type: r.mime || 'image/png', data: r.b64 },
}));
content.push({ type: 'text', text });

const claude_body = {
  model: 'claude-haiku-4-5-20251001',
  max_tokens: 1200,
  system: [{ type: 'text', text: system }],
  messages: [{ role: 'user', content }],
};
return [{ json: { claude_body } }];

const res = $input.first().json;
const raw = (res.content && res.content[0] && res.content[0].text) ? res.content[0].text : '';
if (!raw) throw new Error('Claude returned no text: ' + JSON.stringify(res.error || res).slice(0, 300));
let txt = raw.trim();
if (txt.startsWith('```')) { txt = txt.substring(txt.indexOf('\n') + 1); if (txt.endsWith('```')) txt = txt.slice(0, -3); txt = txt.trim(); }
const start = txt.indexOf('{'); const end = txt.lastIndexOf('}');
if (start >= 0 && end > start) txt = txt.slice(start, end + 1);
let d = {};
try { d = JSON.parse(txt); } catch (e) { d = { prompt: raw.trim(), brief_check: { passes: false, issues: ['Claude reply was not valid JSON — brief check skipped, review the prompt by eye.'], notes: '' } }; }
const bc = d.brief_check || {};
const brief_check = {
  passes: bc.passes === true,
  issues: Array.isArray(bc.issues) ? bc.issues.map(String) : [],
  notes: (bc.notes || '').toString(),
};
if (brief_check.issues.length) brief_check.passes = false;
return [{ json: { ok: true, prompt: (d.prompt || '').toString().trim(), brief_check } }];
